def check(output: str, ctx: dict) -> bool:
    segs = segments(output)
    return all(segs[i] != segs[i+1] for i in range(len(segs)-1))

def check(output: str, ctx: dict) -> bool:
    vowels = 'aeiouAEIOU'
    return all(any(c in vowels for c in seg) for seg in segments(output))

def check(output: str, ctx: dict) -> bool:
    valid_suffixes = {'ed', 'ing', 's', 'es', 'ly', 'ize', 'ful', 'able', 'ic', 'al'}
    return all(seg.endswith(tuple(valid_suffixes)) or seg.isalpha() for seg in segments(output))

def check(output: str, ctx: dict) -> bool:
    segs = segments(output)
    return len(segs) == len(set(segs))

def check(output: str, ctx: dict) -> bool:
    valid_prefixes = {'un', 're', 'pre', 'sub', 'non', 'mis', 'dis', 'in', 'im', 'ir'}
    return segments(output)[0] in valid_prefixes or segments(output)[0].isalpha()

def check(output: str, ctx: dict) -> bool:
    valid_suffixes = {'ed', 'ing', 's', 'ly', 'ize', 'ful', 'able', 'ic', 'al'}
    segs = segments(output)
    return all(segs[-1].endswith(tuple(valid_suffixes)) or segs[-1].isalpha())
